const payload = $input.first().json.body ?? $input.first().json;
const recipients = payload.recipients?.email ?? [];
const santri = payload.santri ?? {};
const orangTua = payload.orang_tua ?? {};
const alamat = payload.alamat ?? {};
const group = payload.group ?? {};
const ringkasan = payload.ringkasan?.baris ?? {};

const summaryRows = Object.entries(ringkasan)
  .map(([label, value]) => `<tr><td style="padding:6px 10px;border:1px solid #e5e7eb;font-weight:700;background:#f8fafc;">${label}</td><td style="padding:6px 10px;border:1px solid #e5e7eb;">${value ?? '-'}</td></tr>`)
  .join('');

const html = `
<div style="font-family:Arial,sans-serif;color:#0f172a;line-height:1.55;">
  <h2 style="margin:0 0 12px;color:#047857;">Pendaftaran SPSB Berhasil Diterima</h2>
  <p>Assalamu'alaikum Bapak/Ibu,</p>
  <p>Alhamdulillah, data pendaftaran ananda <strong>${santri.nama_lengkap ?? '-'}</strong> telah masuk ke sistem SPSB.</p>
  <table style="border-collapse:collapse;width:100%;max-width:720px;margin:16px 0;font-size:14px;">
    ${summaryRows}
    <tr><td style="padding:6px 10px;border:1px solid #e5e7eb;font-weight:700;background:#f8fafc;">Nama Ayah</td><td style="padding:6px 10px;border:1px solid #e5e7eb;">${orangTua.ayah?.nama ?? '-'}</td></tr>
    <tr><td style="padding:6px 10px;border:1px solid #e5e7eb;font-weight:700;background:#f8fafc;">Nama Ibu</td><td style="padding:6px 10px;border:1px solid #e5e7eb;">${orangTua.ibu?.nama ?? '-'}</td></tr>
    <tr><td style="padding:6px 10px;border:1px solid #e5e7eb;font-weight:700;background:#f8fafc;">Alamat</td><td style="padding:6px 10px;border:1px solid #e5e7eb;">${alamat.alamat_lengkap ?? '-'}, ${alamat.kelurahan_desa ?? '-'}, ${alamat.kecamatan ?? '-'}</td></tr>
  </table>
  <p><strong>Informasi grup kelas:</strong><br>${group.aturan ?? '-'}</p>
  <p>Link grup kelas: <a href="${group.link ?? '#'}">${group.link ?? '-'}</a></p>
  <p>Dokumen cetak pendaftaran dapat dibuka melalui tautan berikut:<br><a href="${payload.links?.cetak ?? '#'}">${payload.links?.cetak ?? '-'}</a></p>
  <p style="margin-top:20px;">Jazakumullah khairan,<br>Panitia SPSB</p>
</div>`;

return recipients.map((recipient) => ({
  json: {
    to_email: recipient.email,
    to_name: recipient.name,
    subject: `Ringkasan Pendaftaran SPSB - ${santri.nama_lengkap ?? ''}`,
    html,
    payload
  }
}));
